import type { Metadata } from "next";
import { connection } from "next/server";
import { Suspense } from "react";

import * as api from "@/lib/api";
import { must } from "@/lib/backend";
import { readHorsePicker } from "@/lib/reads";

import HorsePicker from "@/components/common/horse-picker";
import JoinHerd from "@/components/common/join-herd";

export const metadata: Metadata = { title: "Pick" };

export default function Page() {
    return (
        <main className="flex flex-1 flex-col">
            <Suspense fallback={<p className="px-4 py-16 text-center text-muted-foreground">Loading…</p>}>
                <Sections />
            </Suspense>
        </main>
    );
}

// Sections streams in after the page's shell.
async function Sections() {
    await connection();
    const loaded = await must(api.horses.list());
    const props1 = await readHorsePicker(loaded);
    return (
        <>
            {props1.horses.length === 0 ? <p className="mx-auto w-full max-w-5xl px-4 py-16 text-center text-muted-foreground sm:px-6">{"No horses yet."}</p> : <HorsePicker {...props1} />}
            <JoinHerd />
        </>
    );
}
